1	import java.math.BigDecimal;
2	import java.util.List;
3	
4	/**
5	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
6	 * fee, applied to the base premium the {@link PriceList} states for the insured
7	 * items.
8	 *
9	 * A premium is a charge to the customer, so its fraction of a G is rounded in
10	 * the office's favor by {@link InOfficesFavor}.
11	 */
12	public class PremiumPolicy {
13	
14	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
15	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
16	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
17	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
18	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = new BigDecimal("0.15");
19	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
20	
21	    private final PriceList priceList;
22	
23	    /** The premium rules read their base premiums from the office's price list. */
24	    public PremiumPolicy(PriceList priceList) {
25	        this.priceList = priceList;
26	    }
27	
28	    /**
29	     * The office charges both kinds of modifier on a base premium, never on each
30	     * other: an item modifier on the affected item's own base premium, a
31	     * policy-wide modifier on the policy base premium. So the two are summed
32	     * alongside the base premium rather than compounded in sequence, and the
33	     * processing fee is added at the very end.
34	     */
35	    public int quote(Customer customer, List<InsuredItem> insuredItems) {
36	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
37	        BigDecimal premium = policyBasePremium
38	                .add(itemRiskSurcharges(insuredItems))
39	                .add(policyWideModifiers(policyBasePremium, customer))
40	                .add(PROCESSING_FEE);
41	        return InOfficesFavor.charge(premium).intValueExact();
42	    }
43	
44	    /**
45	     * Item-scope modifiers: each is charged on the base premium of the affected
46	     * item alone, so a modifier on one item never touches another item's share
47	     * of the policy. What one item's risks cost is {@link #riskSurcharge}'s
48	     * business; this rule only states that the policy owes the sum of them.
49	     */
50	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
51	        BigDecimal surcharges = BigDecimal.ZERO;
52	        for (InsuredItem insuredItem : insuredItems) {
53	            surcharges = surcharges.add(riskSurcharge(insuredItem));
54	        }
55	        return surcharges;
56	    }
57	
58	    /**
59	     * What the risks the office reads in one item cost, charged on that item's
60	     * own base premium. A curse and a high enchantment are separate risks, so an
61	     * item carrying both is surcharged for both rather than letting the graver
62	     * risk absorb the other.
63	     */
64	    private BigDecimal riskSurcharge(InsuredItem insuredItem) {
65	        BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
66	        BigDecimal surcharge = BigDecimal.ZERO;
67	        if (insuredItem.cursed()) {
68	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
69	        }
70	        if (insuredItem.isHighlyEnchanted()) {
71	            surcharge = surcharge.add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
72	        }
73	        return surcharge;
74	    }
75	
76	    /**
77	     * Policy-scope modifiers: each is charged on the policy base premium, the
78	     * sum of all item base premiums. Every quote is a first insurance of the
79	     * items it covers, whatever the customer's history.
80	     */
81	    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium, Customer customer) {
82	        return firstInsuranceSurcharge(policyBasePremium)
83	                .subtract(loyaltyDiscount(policyBasePremium, customer))
84	                .subtract(followUpContractDiscount(policyBasePremium, customer));
85	    }
86	
87	    /**
88	     * Every contract after the customer's first earns a discount, however long
89	     * they have been with the office.
90	     */
91	    private static BigDecimal followUpContractDiscount(BigDecimal policyBasePremium,
92	            Customer customer) {
93	        if (!customer.holdsFollowUpContract()) {
94	            return BigDecimal.ZERO;
95	        }
96	        return policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
97	    }
98	
99	    /**
100	     * Every quote is a first insurance of the items it covers, whatever the
101	     * customer's history, so this surcharge is charged on every policy.
102	     */
103	    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
104	        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
105	    }
106	
107	    /**
108	     * The office rewards a long-standing customer with a discount on the policy
109	     * base premium. Who counts as long-standing is the customer's standing to
110	     * answer; this rule only states what that standing is worth.
111	     */
112	    private static BigDecimal loyaltyDiscount(BigDecimal policyBasePremium, Customer customer) {
113	        if (!customer.isLongStanding()) {
114	            return BigDecimal.ZERO;
115	        }
116	        return policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE);
117	    }
118	}
