1	import java.math.BigDecimal;
2	import java.math.RoundingMode;
3	
4	/**
5	 * The MHPCO rounds every amount to whole G in its own favor. One rule, read in
6	 * the direction the money moves: a fraction of a G the customer owes the office
7	 * is rounded up, a fraction the office owes the customer is rounded down. The
8	 * office never loses the fraction.
9	 *
10	 * Intermediate amounts during a calculation stay exact fractions; only a final
11	 * charge or payment is rounded.
12	 */
13	final class InOfficesFavor {
14	
15	    private static final int WHOLE_G = 0;
16	
17	    private InOfficesFavor() {
18	    }
19	
20	    /** What the customer owes the office, rounded up: the fraction favors the office. */
21	    static BigDecimal charge(BigDecimal amount) {
22	        return amount.setScale(WHOLE_G, RoundingMode.CEILING);
23	    }
24	
25	    /** What the office owes the customer, rounded down: the fraction favors the office. */
26	    static BigDecimal payment(BigDecimal amount) {
27	        return amount.setScale(WHOLE_G, RoundingMode.FLOOR);
28	    }
29	}
